head.src/retry.mjs:
export function retryDelay(env = process.env) {
  return Number(env.RETRY_DELAY_SECONDS ?? 5);
}

head.test/retry.test.mjs:
import assert from 'node:assert/strict';
import { retryDelay } from '../src/retry.mjs';
assert.equal(retryDelay({ RETRY_DELAY_SECONDS: '5' }), 5000, 'retry delay uses milliseconds');
